Definition hs_shadow_ok (A : atable) (ch : acs) : bool :=
  (let '(sb, sk, sn) := shadow_of A (kn ch) e_band e_bandlen in
   ((if kzero_x (kn ch) (kn ch) sb sk sn then true else kzero2L (kn ch) sb sk sn) && kwritable_x (kn ch) (kn ch) sb sk sn))
  && kwritable (kn ch) (kn ch) (ELit 0) 0x7fffa000 0xf1400 && known_cover (kn ch) 0x7fffa000 0x800eb400 (S (length (kn ch)))
  && hs_static_ok ch.

Lemma kknown_at_sound : forall E M k cur h, know_ok asegs E M k -> kknown_at k cur = Some h ->
  cur < h /\ forall z, cur <= z < h -> mrd asegs M (wa z) <> None.
Proof.
