Definition hs_rt_ok (A : atable) (ch : acs) : bool :=
  (hs_lay_ok ch && hs_consts_ok ch && hs_zero_ok ch && hs_primsh_ok A ch && hs_fs_ok ch && hs_dep_ok ch && hs_ia_ok ch
